		nvgScissor(vg, tx, kReadout.y0 + 17.0f, tw, 44.0f);
		nvgFillColor(vg, nvgRGBA(255, 204, 153, 255 * targDisplayTxt.textDisplayDecay));
		nvgText(vg, tx, kReadout.y0 + 27.0f, targDisplayTxt.selectedCtrlTargBuilder.c_str(), NULL);
