	void NVGView::fillGrid(float x, float y, float w, float h) {
		using namespace ::editorLayout;
		if (images[GRID_TILE] < 1) {
			// Same colours as the grid painted in bkg1.png: line pixels on multiples of 5.
			unsigned char tile[kGridStep * kGridStep * 4];
			for (int ty = 0; ty < kGridStep; ty++) {
				for (int tx = 0; tx < kGridStep; tx++) {
					unsigned char* p = &tile[(ty * kGridStep + tx) * 4];
					const bool line = (tx == 0 || ty == 0);
					p[0] = line ? 4 : 11;
					p[1] = line ? 5 : 12;
					p[2] = line ? 16 : 23;
					p[3] = 255;
				}
			}
			images[GRID_TILE] = nvgCreateImageRGBA(vg, kGridStep, kGridStep,
				NVG_IMAGE_REPEATX | NVG_IMAGE_REPEATY | NVG_IMAGE_NEAREST, tile);
		}
		if (w <= 0 || h <= 0)
			return;
		NVGpaint gridPaint = nvgImagePattern(vg, 0, 0, kGridStep, kGridStep, 0.0f, images[GRID_TILE], 1.0f);
		nvgBeginPath(vg);
		nvgRect(vg, x, y, w, h);
		nvgFillPaint(vg, gridPaint);
		nvgFill(vg);
	}

	void NVGView::drawGrid(const ::editorLayout::ImageRect& img) {
		using namespace ::editorLayout;
		// Only outside the image: the art has transparent windows that the envelope/LFO displays
		// (drawn before the background) show through, so the grid must not cover them.
		const float ax0 = img.x, ay0 = img.y;
		const float ax1 = img.x + img.w, ay1 = img.y + img.h;
		const float W = kEditorWidth, H = kEditorHeight;
		const float my0 = ay0 > 0 ? ay0 : 0, my1 = ay1 < H ? ay1 : H;
		fillGrid(0, 0, W, ay0);                    // above
		fillGrid(0, ay1, W, H - ay1);              // below
		fillGrid(0, my0, ax0, my1 - my0);          // left
		fillGrid(ax1, my0, W - ax1, my1 - my0);    // right
	}

	// ---- block hover effect (2026-11-17) ------------------------------------------------------
	// The blocks are the framed control strips of the art (MAIN OSC / MOD OSC / GLOBAL row and the
	// ENV/LFO blocks); their outlines and the PCB trace pixels come from the panel SVG
	// (tools/blockmap/blockmap.py -> blockMap.h). The block under the mouse:
	//   - border glow and a light cyan lift of its area, eased in/out (blockAmt);
	//   - on entering, one pass of energy (0.9 s): a bright front with a fading tail runs down the
	//     block, lighting the traces it crosses (a tinted copy of the trace mask, scissored to thin
	//     strips). No sparks, and the border is not part of the pass (2026-11-17).
	// Additive blending throughout; drawn by drawBkg over the art and under the controls.
	namespace {
		const float kBlockFxDur = 0.9f;   // energy pass, seconds
		const float kBlockFxGain = 0.5f;  // energy pass opacity (halved 2026-11-17: subtler)

		float smooth01(float a, float b, float x) {
			float t = (x - a) / (b - a);
			t = t < 0.0f ? 0.0f : (t > 1.0f ? 1.0f : t);
			return t * t * (3.0f - 2.0f * t);
		}

		// the STEP CTRL buttons (row 2) are drawn editorLayout::kStepDY below their place in the art
		float blockDY(const blockMap::Block& b) {
			return b.row == 2 ? static_cast<float>(::editorLayout::kStepDY) : 0.0f;
		}

		void blockPath(NVGcontext* vg, const blockMap::Block& b) {
			const float dy = blockDY(b);
			nvgBeginPath(vg);
			nvgMoveTo(vg, b.p[0].x, b.p[0].y + dy);
			for (int i = 1; i < b.n; i++)
				nvgLineTo(vg, b.p[i].x, b.p[i].y + dy);
			nvgClosePath(vg);
		}

		bool inBlock(const blockMap::Block& b, float x, float y) {
			y -= blockDY(b);
			bool c = false;
			for (int i = 0, j = b.n - 1; i < b.n; j = i++) {
				const float xi = b.p[i].x, yi = b.p[i].y, xj = b.p[j].x, yj = b.p[j].y;
				if ((yi > y) != (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi)
					c = !c;
			}
			return c;
		}

		void blockBounds(const blockMap::Block& b, float& x0, float& y0, float& x1, float& y1) {
			x0 = x1 = b.p[0].x;
			y0 = y1 = b.p[0].y;
			for (int i = 1; i < b.n; i++) {
				x0 = std::min(x0, b.p[i].x);
				x1 = std::max(x1, b.p[i].x);
				y0 = std::min(y0, b.p[i].y);
				y1 = std::max(y1, b.p[i].y);
			}
			y0 += blockDY(b);
			y1 += blockDY(b);
		}

		// The sections of the right column's frame (row 3, editorLayout::column::kFrame*): glow and lift
		// only, like the step buttons. Indices after the generated blocks.
		namespace ec = ::editorLayout::column;
		const blockMap::Block kColBlocks[] = {
			// MASTER / PLAY / DELAY meet along the tabbed divider paths (drawColumnFrame)
			{"MASTER", 3, 7, {{ec::kFrameL, ec::kFrameT + 6.0f}, {ec::kFrameL + 6.0f, ec::kFrameT}, {ec::kFrameR, ec::kFrameT}, {ec::kFrameR, ec::kPlayLine},
			                  {ec::kPlayTabX + ec::kTabH, ec::kPlayLine}, {ec::kPlayTabX, ec::kPlayLine - ec::kTabH}, {ec::kFrameL, ec::kPlayLine - ec::kTabH}}},
			{"PLAY", 3, 8, {{ec::kFrameL, ec::kPlayLine - ec::kTabH}, {ec::kPlayTabX, ec::kPlayLine - ec::kTabH}, {ec::kPlayTabX + ec::kTabH, ec::kPlayLine}, {ec::kFrameR, ec::kPlayLine},
			                {ec::kFrameR, ec::kFxLine}, {ec::kFxTabX + ec::kTabH, ec::kFxLine}, {ec::kFxTabX, ec::kFxLine - ec::kTabH}, {ec::kFrameL, ec::kFxLine - ec::kTabH}}},
			{"DELAY", 3, 7, {{ec::kFrameL, ec::kFxLine - ec::kTabH}, {ec::kFxTabX, ec::kFxLine - ec::kTabH}, {ec::kFxTabX + ec::kTabH, ec::kFxLine}, {ec::kFrameR, ec::kFxLine},
			                 {ec::kFrameR, ec::kFrameB - 12.0f}, {ec::kFrameR - 12.0f, ec::kFrameB}, {ec::kFrameL, ec::kFrameB}}},
			{"CHORUS", 3, 5, {{ec::kChorusL, ec::kChorusT + 9.0f}, {ec::kChorusL + 9.0f, ec::kChorusT}, {ec::kFrameL, ec::kChorusT}, {ec::kFrameL, ec::kFrameB}, {ec::kChorusL, ec::kFrameB}}},
		};
		constexpr int kAllBlocks = blockMap::kBlockCount + static_cast<int>(sizeof(kColBlocks) / sizeof(kColBlocks[0]));

		const blockMap::Block& blockRef(int i) {
			return i < blockMap::kBlockCount ? blockMap::kBlocks[i] : kColBlocks[i - blockMap::kBlockCount];
		}
	}
	static_assert(kAllBlocks <= NVGView::kMaxBlocks, "NVGView block state arrays too small");

	int NVGView::blockAt(float x, float y) {
		for (int i = 0; i < kAllBlocks; i++)
			if (inBlock(blockRef(i), x, y))
				return i;
		return -1;
	}

	CMouseEventResult NVGView::onMouseMoved(CFrame* frame, const CPoint& where, const CButtonState& buttons) {
		blockMouse = where;
		blockMouseValid = true;
		return kMouseEventNotHandled;
	}

	void NVGView::updateBlockHover() {
		using namespace ::editorLayout;
		int hit = -1;
		if (blockHoverForce >= 0) {
			hit = blockHoverForce < kAllBlocks ? blockHoverForce : -1;
		}
		else if (blockMouseValid) {
			// The frame reports moves but not always the exit from the window: ask where the mouse is.
			CFrame* f = getFrame();
			CPoint p;
			if (f && f->getCurrentMouseLocation(p) && (p.x < 0 || p.y < 0 || p.x >= kEditorWidth || p.y >= kEditorHeight))
				blockMouseValid = false;
			else
				hit = blockAt(static_cast<float>(blockMouse.x), static_cast<float>(blockMouse.y));
			// while a knob is dragged, stay on the block the drag started in
			if (f && blockHover >= 0 && (f->getCurrentMouseButtons().getButtonState() & kLButton))
				hit = blockHover;
		}
		if (hit != blockHover) {
			if (blockHover >= 0)
				blockFxOn[blockHover] = false;  // leaving a block ends its pass: only the hovered block shows one
			if (hit >= 0 && blockRef(hit).row < 2) {  // step buttons and column sections have no traces: glow and lift only
				blockFxOn[hit] = true;
				blockFxT[hit] = 0.0f;
			}
			blockHover = hit;
		}
		for (int i = 0; i < kAllBlocks; i++) {
			const float target = i == blockHover ? 1.0f : 0.0f;
			const float tau = target > blockAmt[i] ? 0.06f : 0.22f;
			blockAmt[i] += (target - blockAmt[i]) * (1.0f - std::exp(-frameDt / tau));
			if (blockFxOn[i]) {
				blockFxT[i] += frameDt;
				if (blockFxT[i] >= kBlockFxDur)
					blockFxOn[i] = false;
			}
		}
		if (blockFxFreeze >= 0.0f && blockHover >= 0 && blockRef(blockHover).row < 2) {
			blockAmt[blockHover] = 1.0f;
			blockFxOn[blockHover] = true;
			blockFxT[blockHover] = blockFxFreeze * kBlockFxDur;
		}
	}

	void NVGView::drawBlockFx() {
		using namespace ::editorLayout;
		const int W = kEditorWidth, H = kEditorHeight;
		if (images[TRACE_MASK] < 1) {
			// The traces are painted at alpha <= ~100; the mask is scaled so a trace is fully lit.
			std::vector<unsigned char> rgba(static_cast<size_t>(W) * H * 4, 0);
			for (int i = 0; i < blockMap::kTraceCount; i++) {
				const blockMap::TracePx& t = blockMap::kTrace[i];
				if (t.x >= W || t.y >= H)
					continue;
				const size_t k = static_cast<size_t>(t.y) * W + t.x;
				const unsigned char a = static_cast<unsigned char>(std::min(255, t.a * 255 / 90));
				rgba[k * 4 + 0] = rgba[k * 4 + 1] = rgba[k * 4 + 2] = 255;
				rgba[k * 4 + 3] = a;
			}
			images[TRACE_MASK] = nvgCreateImageRGBA(vg, W, H, NVG_IMAGE_NEAREST, rgba.data());
		}
		updateBlockHover();

		nvgSave(vg);
		nvgGlobalCompositeOperation(vg, NVG_LIGHTER);
		nvgLineJoin(vg, NVG_ROUND);
		for (int bi = 0; bi < kAllBlocks; bi++) {
			const float amt = blockAmt[bi];
			const bool fx = blockFxOn[bi];
			if (amt < 0.004f && !fx)
				continue;
			const blockMap::Block& b = blockRef(bi);
			float bx0, by0, bx1, by1;
			blockBounds(b, bx0, by0, bx1, by1);

			// area: a light cyan lift, stronger at the top (not over an ENV/LFO display window)
			if (amt > 0.004f) {
				blockPath(vg, b);
				int win = 0;  // index of the block among the ENV/LFO blocks = its display window
				for (int k = 0; k < bi; k++)
					win += blockRef(k).row == 1 ? 1 : 0;
				if (b.row == 1 && win < 6) {
					const ImageRect& r = kDisplayWin[win];
					nvgRect(vg, static_cast<float>(r.x), static_cast<float>(r.y), static_cast<float>(r.w), static_cast<float>(r.h));
					nvgPathWinding(vg, NVG_HOLE);
				}
				nvgFillPaint(vg, nvgLinearGradient(vg, 0, by0, 0, by1, nvgRGBA(60, 170, 220, static_cast<unsigned char>(34 * amt)),
				                                   nvgRGBA(60, 170, 220, static_cast<unsigned char>(12 * amt))));
				nvgFill(vg);
				// border glow: wide soft passes under a bright core
				blockPath(vg, b);
				nvgStrokeColor(vg, nvgRGBA(4, 186, 232, static_cast<unsigned char>(22 * amt)));
				nvgStrokeWidth(vg, 9.0f);
				nvgStroke(vg);
				nvgStrokeColor(vg, nvgRGBA(30, 200, 245, static_cast<unsigned char>(45 * amt)));
				nvgStrokeWidth(vg, 5.0f);
				nvgStroke(vg);
				nvgStrokeColor(vg, nvgRGBA(150, 238, 255, static_cast<unsigned char>(140 * amt)));
				nvgStrokeWidth(vg, 2.0f);
				nvgStroke(vg);
			}

			if (!fx)
				continue;
			// energy pass: the front runs from the top to past the bottom (ease in/out), fading in and out
			const float u = blockFxT[bi] / kBlockFxDur;
			const float env = smooth01(0.0f, 0.12f, u) * (1.0f - smooth01(0.55f, 1.0f, u));
			if (env < 0.003f)
				continue;
			const float tail = b.row == 0 ? 38.0f : 24.0f;
			const float pu = std::min(1.0f, u / 0.85f);
			const float ease = pu * pu * (3.0f - 2.0f * pu);
			const float front = by0 - 2.0f + (by1 - by0 + tail * 0.5f) * ease;
			NVGpaint trace = nvgImagePattern(vg, 0, 0, static_cast<float>(W), static_cast<float>(H), 0.0f, images[TRACE_MASK], 1.0f);
			const int kStrips = 10;
			for (int s = -1; s < kStrips; s++) {
				// s = -1: the head (2 px, brightest); then the tail strips upwards, fading
				float ya, yb, a;
				if (s < 0) {
					ya = front;
					yb = front + 2.0f;
					a = 1.0f;
				}
				else {
					ya = front - tail * (s + 1) / kStrips;
					yb = front - tail * s / kStrips;
					a = std::pow(1.0f - static_cast<float>(s) / kStrips, 1.6f) * 0.8f;
				}
				ya = std::max(ya, by0 - 2.0f);
				yb = std::min(yb, by1 + 2.0f);
				if (yb <= ya)
					continue;
				a *= env * kBlockFxGain;
				nvgScissor(vg, bx0 - 6.0f, ya, bx1 - bx0 + 12.0f, yb - ya);
				trace.innerColor = nvgRGBAf(0.55f, 0.93f, 1.0f, a);
				blockPath(vg, b);
				nvgFillPaint(vg, trace);
				nvgFill(vg);
				// halo: the mask again 1 px left and right, dimmer, so a lit trace reads as a glow
				for (int dx = -1; dx <= 1; dx += 2) {
					NVGpaint halo = nvgImagePattern(vg, static_cast<float>(dx), 0, static_cast<float>(W), static_cast<float>(H), 0.0f, images[TRACE_MASK], 1.0f);
					halo.innerColor = nvgRGBAf(0.2f, 0.75f, 1.0f, a * 0.4f);
					blockPath(vg, b);
					nvgFillPaint(vg, halo);
					nvgFill(vg);
				}
			}
			nvgResetScissor(vg);
		}
		nvgRestore(vg);
	}

	void NVGView::drawPanelBase() {
		using namespace ::editorLayout;
		fillGrid(0, 0, static_cast<float>(kEditorWidth), static_cast<float>(kEditorHeight));
		for (const ImageRect& r : kDisplayWin) {
			nvgBeginPath(vg);
			nvgRect(vg, static_cast<float>(r.x), static_cast<float>(r.y), static_cast<float>(r.w), static_cast<float>(r.h));
			nvgFillColor(vg, nvgRGBA(0, 0, 0, 255));
			nvgFill(vg);
		}
	}

	void NVGView::drawBkg(RData& reIn) {
		using namespace ::editorLayout;
		// The panel image is drawn at kPanelImg (editorLayout.h), over the grid of drawPanelBase.
		NVGpaint imgPaint;
		imgPaint = nvgImagePattern(vg, kPanelImg.x, kPanelImg.y, kPanelImg.w, kPanelImg.h, 0.0f, images[MAIN_ROW_BKG], 1.0);
		nvgBeginPath(vg);
		nvgRect(vg, kPanelImg.x, kPanelImg.y, kPanelImg.w, kPanelImg.h);
		nvgRect(vg, kStepArt.x, kStepArt.y, kStepArt.w, kStepArt.h);
		nvgPathWinding(vg, NVG_HOLE);
		nvgFillPaint(vg, imgPaint);
		nvgFill(vg);
		// the STEP CTRL section of the art, kStepDY lower (kStepDY is a multiple of the 5 px grid)
		imgPaint = nvgImagePattern(vg, kPanelImg.x, kPanelImg.y + kStepDY, kPanelImg.w, kPanelImg.h, 0.0f, images[MAIN_ROW_BKG], 1.0);
		nvgBeginPath(vg);
		nvgRect(vg, kStepArt.x, kStepArt.y + kStepDY, kStepArt.w, kStepArt.h);
		nvgFillPaint(vg, imgPaint);
		nvgFill(vg);

		drawRightColumn();
		drawBlockFx();  // block hover effect, over the art and the column frame, under the controls
	}

	// ---- right column ------------------------------------------------------------------------
	namespace {
		const NVGcolor kColFrame = nvgRGBA(4, 186, 232, 255);   // frame cyan of the art
		const NVGcolor kColLabel = nvgRGBA(0, 204, 255, 255);   // label text cyan of the art
		const NVGcolor kColMagenta = nvgRGBA(93, 32, 93, 255);  // CONTROL box magenta of the art
		const NVGcolor kColDimFrame = nvgRGBA(4, 186, 232, 120);
		const NVGcolor kColDivider = nvgRGBA(160, 44, 170, 255);  // bracket of the CONTROL slots
	}

	// The frame of the lower right (2026-11-17, after the user's mock-up): one outline in the art's
	// frame cyan around MASTER, PLAY and DELAY that steps left at kChorusT to take in CHORUS, with the
	// art's chamfered corners and a faint dark fill; dividers in the same cyan: the CHORUS | DELAY
	// separator (the frame's left edge continued down) and the PLAY and DELAY lines, each stepping up
	// over its section label in a tab (like the art's header tabs). Revised the same day: dividers were
	// magenta and also ran under the labels.
	void NVGView::drawColumnFrame() {
		using namespace ::editorLayout::column;
		nvgBeginPath(vg);
		nvgMoveTo(vg, kFrameL, kFrameT + 6.0f);
		nvgLineTo(vg, kFrameL + 6.0f, kFrameT);
		nvgLineTo(vg, kFrameR, kFrameT);
		nvgLineTo(vg, kFrameR, kFrameB - 12.0f);
		nvgLineTo(vg, kFrameR - 12.0f, kFrameB);
		nvgLineTo(vg, kChorusL, kFrameB);
		nvgLineTo(vg, kChorusL, kChorusT + 9.0f);
		nvgLineTo(vg, kChorusL + 9.0f, kChorusT);
		nvgLineTo(vg, kFrameL, kChorusT);
		nvgClosePath(vg);
		nvgFillPaint(vg, nvgLinearGradient(vg, 0, kFrameT, 0, kFrameB, nvgRGBA(10, 40, 62, 120), nvgRGBA(2, 10, 20, 150)));
		nvgFill(vg);
		nvgLineJoin(vg, NVG_MITER);
		nvgStrokeColor(vg, kColFrame);
		nvgStrokeWidth(vg, 2.0f);
		nvgStroke(vg);

		// dividers, in the frame's cyan and width (the hover outlines of the sections follow them):
		// the CHORUS | DELAY separator, and the PLAY / DELAY lines, which step over their section label
		// (tab top from the frame to kPlayTabX / kFxTabX, 45 degree slant down, then along the line)
		nvgBeginPath(vg);
		nvgMoveTo(vg, kFrameL, kChorusT);
		nvgLineTo(vg, kFrameL, kFrameB);
		auto line = [&](float y, float tabX) {
			nvgMoveTo(vg, kFrameL, y - kTabH);
			nvgLineTo(vg, tabX, y - kTabH);
			nvgLineTo(vg, tabX + kTabH, y);
			nvgLineTo(vg, kFrameR, y);
		};
		line(kPlayLine, kPlayTabX);
		line(kFxLine, kFxTabX);
		nvgStrokeColor(vg, kColFrame);
		nvgStrokeWidth(vg, 2.0f);
		nvgStroke(vg);
	}

	// PLAY and FX rows in the right column (2026-11-15): section labels, knob wells and labels; the
	// knobs and toggles are normal controls (vstgui.uidesc) drawn by drawKnob/drawButton.
	void NVGView::drawPlayPanel() {
		using namespace ::editorLayout::column;
		const float lx = kX0 + 9;
		drawColumnSectionLabel(lx, kPlay.y0 + 2, "PLAY");
		const char* labels[4] = {"SNAP", "DRIFT", "EXPR", ""};
		if (baseController)
			labels[3] = exprTargetName(exprTargetFromNormalized(baseController->getParamNormalized(EXPR_TARGET)));
		nvgFontSize(vg, 9.0f);
		nvgFontFace(vg, "mono");
		nvgFillColor(vg, kColLabel);
		nvgTextAlign(vg, NVG_ALIGN_CENTER | NVG_ALIGN_TOP);
		// DRIFT, EXPR and the target knob sit kPlayLowDY lower than SNAP (right of the PLAY tab's slant,
		// where the divider is lower; #driftAmount/#exprAmount/#exprTarget at y 429, SNAP at 418)
		for (int i = 0; i < 4; i++)
			nvgText(vg, slotCenterX(i), kPlay.y0 + kRowLabelDY + (i ? kPlayLowDY : 0.0f), labels[i], NULL);
		// the SYNC (#keySync, 1086,400: OSC KEY SYNC), HQ (#hqMode, 1140,400) and VEL (#exprVel, 1184,400)
		// toggles, above the PLAY divider, are labelled to their right
		nvgTextAlign(vg, NVG_ALIGN_LEFT | NVG_ALIGN_MIDDLE);
		nvgText(vg, 1110.0f + kDX, 389.5f + kDY, "SYNC", NULL);
		nvgText(vg, 1164.0f + kDX, 389.5f + kDY, "HQ", NULL);
		nvgText(vg, 1208.0f + kDX, 389.5f + kDY, "VEL", NULL);

		// FX row: the ping-pong delay (the chorus sits in the panel next to STEP CTRL TARGET)
		drawColumnSectionLabel(lx, kFx.y0 + 2, "DELAY");
		const char* fxLabels[4] = {"", "FEEDBACK", "TONE", "MIX"};
		if (baseController)
			fxLabels[0] = fx::delayDivisionName(fx::delayDivisionFromNormalized(baseController->getParamNormalized(DLY_TIME)));
		nvgFontSize(vg, 9.0f);
		nvgFontFace(vg, "mono");
		nvgFillColor(vg, kColLabel);
		nvgTextAlign(vg, NVG_ALIGN_CENTER | NVG_ALIGN_TOP);
		for (int i = 0; i < 4; i++)
			nvgText(vg, slotCenterX(i), kFx.y0 + kRowLabelDY, fxLabels[i], NULL);

		// CHORUS, right of STEP CTRL TARGET, no frame (2026-11-17): the knobs (#choRate/#choDepth/#choMix,
		// origins 760/810/860,488) sit under LFO 3's knobs; the label bottoms line up with the bottom of
		// the art's STEP CTRL TARGET label (y 517 + kStepDY), and with the DELAY labels (kFx).
		drawColumnSectionLabel(747.0f, 469.0f, "CHORUS");
		static const char* const choLabels[3] = {"RATE", "DEPTH", "MIX"};
		static const float choX[3] = {775.0f, 825.0f, 875.0f};
		nvgFontSize(vg, 9.0f);
		nvgFontFace(vg, "mono");
		nvgFillColor(vg, kColLabel);
		nvgTextAlign(vg, NVG_ALIGN_CENTER | NVG_ALIGN_TOP);
		for (int i = 0; i < 3; i++)
			nvgText(vg, choX[i], 521.0f, choLabels[i], NULL);
	}

	void NVGView::drawImageAt(int image, float x, float y, float w, float h) {
		if (images[image] < 1)
			return;
		NVGpaint p = nvgImagePattern(vg, x, y, w, h, 0.0f, images[image], 1.0f);
		nvgBeginPath(vg);
		nvgRect(vg, x, y, w, h);
		nvgFillPaint(vg, p);
		nvgFill(vg);
	}

	void NVGView::drawColumnSectionLabel(float x, float y, const char* text) {
		nvgFontSize(vg, 11.0f);
		nvgFontFace(vg, "mono");
		nvgTextAlign(vg, NVG_ALIGN_LEFT | NVG_ALIGN_TOP);
		nvgFillColor(vg, kColLabel);
		nvgText(vg, x, y, text, NULL);
	}

	void NVGView::drawInset(float x, float y, float w, float h, NVGcolor border) {
		// Black slot with a chamfered bottom-right corner, like the art's CONTROL/VALUE boxes.
		const float c = 5.0f;
		nvgBeginPath(vg);
		nvgMoveTo(vg, x, y);
		nvgLineTo(vg, x + w, y);
		nvgLineTo(vg, x + w, y + h - c);
		nvgLineTo(vg, x + w - c, y + h);
		nvgLineTo(vg, x, y + h);
		nvgClosePath(vg);
		nvgFillColor(vg, nvgRGBA(0, 0, 0, 255));
		nvgFill(vg);
		nvgStrokeColor(vg, border);
		nvgStrokeWidth(vg, 2.0f);
		nvgStroke(vg);
	}

	void NVGView::drawKnobWell(const ::editorLayout::column::Rect& k, int ticks) {
		// The art paints a dark well and tick dots under each knob; the moved knobs need their own.
		const float cx = k.x + k.w * 0.5f, cy = k.y + k.h * 0.5f, r = k.w * 0.5f;
		NVGpaint well = nvgRadialGradient(vg, cx, cy - r * 0.3f, r * 0.1f, r, nvgRGBA(25, 56, 78, 255), nvgRGBA(6, 6, 10, 255));
		nvgBeginPath(vg);
		nvgCircle(vg, cx, cy, r);
		nvgFillPaint(vg, well);
		nvgFill(vg);
		// ticks over the knob's 270 degree range (angle-start 135)
		const float a0 = NVG_PI * 0.75f, range = NVG_PI * 1.5f;
		nvgFillColor(vg, nvgRGBA(4, 186, 232, 150));
		for (int i = 0; i < ticks; i++) {
			const float a = a0 + range * (ticks > 1 ? float(i) / float(ticks - 1) : 0.5f);
			nvgBeginPath(vg);
			nvgCircle(vg, cx + cosf(a) * (r + 5.0f), cy + sinf(a) * (r + 5.0f), 1.2f);
			nvgFill(vg);
		}
	}

	void NVGView::drawScope(float x, float y, float w, float h) {
		// Inner area of the inset (keep off the frame line and the chamfered corner).
		const float ix = x + 3, iy = y + 3, iw = w - 6, ih = h - 6;
		const float cy = iy + ih * 0.5f;

		// grid: centre line, +-0.5 lines, 8 time divisions
		nvgBeginPath(vg);
		for (int i = 1; i < 8; i++) {
			const float gx = floorf(ix + iw * i / 8.0f) + 0.5f;
			nvgMoveTo(vg, gx, iy);
			nvgLineTo(vg, gx, iy + ih);
		}
		nvgMoveTo(vg, ix, floorf(cy - ih * 0.25f) + 0.5f);
		nvgLineTo(vg, ix + iw, floorf(cy - ih * 0.25f) + 0.5f);
		nvgMoveTo(vg, ix, floorf(cy + ih * 0.25f) + 0.5f);
		nvgLineTo(vg, ix + iw, floorf(cy + ih * 0.25f) + 0.5f);
		nvgStrokeColor(vg, nvgRGBA(4, 186, 232, 28));
		nvgStrokeWidth(vg, 1.0f);
		nvgStroke(vg);
		nvgBeginPath(vg);
		nvgMoveTo(vg, ix, floorf(cy) + 0.5f);
		nvgLineTo(vg, ix + iw, floorf(cy) + 0.5f);
		nvgStrokeColor(vg, nvgRGBA(4, 186, 232, 60));
		nvgStroke(vg);

		// sounding voices behind the waveform (was its own band in column step 4)
		drawScopeVoices(ix, iy, iw, ih);

		if (baseController && baseController->scopeFrames != 0)
			drawScopeWave(ix, iy, iw, ih);

		// voice count (top left) and output peak (top right) over everything
		drawScopeInfo(ix, iy, iw, ih);
	}

	void NVGView::drawScopeWave(float ix, float iy, float iw, float ih) {
		const float cy = iy + ih * 0.5f;

		// waveform: +-1 fills the height (clipped above); one point per frame sample
		const float* f = baseController->scopeFrame;
		const int n = BaseController::kScopeLength;
		const float yScale = ih * 0.5f - 1.0f;
		nvgSave(vg);
		nvgScissor(vg, ix, iy, iw, ih);
		nvgBeginPath(vg);
		for (int i = 0; i < n; i++) {
			float v = f[i];
			if (!(v == v)) v = 0.0f;  // NaN
			v = v > 1.05f ? 1.05f : (v < -1.05f ? -1.05f : v);
			const float px = ix + iw * float(i) / float(n - 1);
			const float py = cy - v * yScale;
			if (i == 0) nvgMoveTo(vg, px, py); else nvgLineTo(vg, px, py);
		}
		nvgLineJoin(vg, NVG_ROUND);
		nvgStrokeColor(vg, nvgRGBA(4, 186, 232, 55));  // glow
		nvgStrokeWidth(vg, 4.0f);
		nvgStroke(vg);
		nvgStrokeColor(vg, nvgRGBA(120, 230, 255, 235));
		nvgStrokeWidth(vg, 1.3f);
		nvgStroke(vg);
		nvgRestore(vg);
	}

	void NVGView::drawPresetBar() {
		if (!baseController)
			return;
		using namespace presetBar;
		baseController->presetBarEnabled = !moreInfoWindowOpen;  // the about window covers the bar
		const int hover = baseController->presetBarEnabled ? baseController->presetHover : -1;
		const NVGcolor kText = nvgRGBA(255, 204, 153, 235);
		const NVGcolor kTextHot = nvgRGBA(255, 236, 210, 255);
		const NVGcolor kCyan = nvgRGBA(4, 186, 232, 255);

		auto hoverFill = [&](int z) {
			const auto& r = kZones[z];
			nvgBeginPath(vg);
			nvgRect(vg, r.x + 1, r.y + 1, r.w - 2, r.h - 2);
			nvgFillColor(vg, nvgRGBA(4, 186, 232, 45));
			nvgFill(vg);
		};
		auto divider = [&](float x) {
			nvgBeginPath(vg);
			nvgMoveTo(vg, floorf(x) + 0.5f, kBar.y + 4);
			nvgLineTo(vg, floorf(x) + 0.5f, kBar.y + kBar.h - 4);
			nvgStrokeColor(vg, nvgRGBA(4, 186, 232, 70));
			nvgStrokeWidth(vg, 1.0f);
			nvgStroke(vg);
		};
		auto arrow = [&](int z, bool left) {
			const auto& r = kZones[z];
			const float cx = r.x + r.w * 0.5f, cy = r.y + r.h * 0.5f, s = 4.0f;
			nvgBeginPath(vg);
			if (left) {
				nvgMoveTo(vg, cx + s * 0.6f, cy - s);
				nvgLineTo(vg, cx - s * 0.8f, cy);
				nvgLineTo(vg, cx + s * 0.6f, cy + s);
			}
			else {
				nvgMoveTo(vg, cx - s * 0.6f, cy - s);
				nvgLineTo(vg, cx + s * 0.8f, cy);
				nvgLineTo(vg, cx - s * 0.6f, cy + s);
			}
			nvgClosePath(vg);
			nvgFillColor(vg, hover == z ? kTextHot : kCyan);
			nvgFill(vg);
		};

		for (int z = 0; z < kZoneCount; z++)
			if (hover == z)
				hoverFill(z);
		divider(kZones[kName].x - 1);
		divider(kZones[kNext].x - 1);
		divider(kZones[kSave].x - 2);
		divider(kZones[kRnd].x - 1);
		arrow(kPrev, true);
		arrow(kNext, false);

		// name, "*" when edited since loaded, and a small menu caret
		const auto& n = kZones[kName];
		std::string name = baseController->presetName.empty() ? std::string("-") : baseController->presetName;
		if (baseController->presetDirty)
			name += " *";
		nvgSave(vg);
		nvgScissor(vg, n.x + 4, n.y, n.w - 18, n.h);
		nvgFontSize(vg, 11.0f);
		nvgFontFace(vg, "mono");
		nvgTextAlign(vg, NVG_ALIGN_LEFT | NVG_ALIGN_MIDDLE);
		nvgFillColor(vg, hover == kName ? kTextHot : kText);
		nvgText(vg, n.x + 6, n.y + n.h * 0.5f + 1.0f, name.c_str(), NULL);
		nvgRestore(vg);
		{
			const float cx = n.x + n.w - 9, cy = n.y + n.h * 0.5f + 1.0f;
			nvgBeginPath(vg);
			nvgMoveTo(vg, cx - 3.5f, cy - 2.0f);
			nvgLineTo(vg, cx + 3.5f, cy - 2.0f);
			nvgLineTo(vg, cx, cy + 2.5f);
			nvgClosePath(vg);
			nvgFillColor(vg, hover == kName ? kTextHot : nvgRGBA(4, 186, 232, 200));
			nvgFill(vg);
		}

		// SAVE and RND
		nvgFontSize(vg, 9.0f);
		nvgFontFace(vg, "mono");
		nvgTextAlign(vg, NVG_ALIGN_CENTER | NVG_ALIGN_MIDDLE);
		const char* labels[2] = {"SAVE", "RND"};
		const int zones[2] = {kSave, kRnd};
		for (int i = 0; i < 2; i++) {
			const auto& r = kZones[zones[i]];
			nvgFillColor(vg, hover == zones[i] ? kTextHot : kColLabel);
			nvgText(vg, r.x + r.w * 0.5f, r.y + r.h * 0.5f + 1.0f, labels[i], NULL);
		}
	}

	void NVGView::drawScopeInfo(float ix, float iy, float iw, float ih) {
		if (!baseController)
			return;
		using clock = std::chrono::steady_clock;
		const auto now = clock::now();

		// peak: hold the largest value for 1.5 s, then follow the incoming level
		if (baseController->peakFrames != peakFramesSeen) {
			peakFramesSeen = baseController->peakFrames;
			const float p = baseController->outPeak;
			if (p >= peakHold || std::chrono::duration<float>(now - peakHoldTime).count() > 1.5f) {
				peakHold = p;
				peakHoldTime = now;
			}
			if (p >= 1.0f) {  // 0 dBFS or more: latch CLIP for 2 s after the last over
				clipLatched = true;
				clipTime = now;
			}
		}
		if (peakFramesSeen == 0)
			peakHold = 0.0f;
		if (clipLatched && std::chrono::duration<float>(now - clipTime).count() > 2.0f)
			clipLatched = false;

		int total = 0, held = 0;
		paramDisplay::countVoices(baseController->voiceStates, total, held);

		const int limit = baseController->polyCount();  // POLY_COUNT; PolyView over this plate edits it
		char left[48];
		if (total == 0)
			snprintf(left, sizeof(left), "VOICES 0/%d", limit);
		else
			snprintf(left, sizeof(left), "VOICES %d/%d  HELD %d", total, limit, held);
		const std::string pk = "PEAK " + paramDisplay::peakText(peakHold);
		const char* right = clipLatched ? "CLIP" : nullptr;

		nvgSave(vg);
		nvgFontSize(vg, 10.0f);
		nvgFontFace(vg, "mono");
		nvgTextAlign(vg, NVG_ALIGN_LEFT | NVG_ALIGN_TOP);
		const float pad = 3.0f, th = 13.0f;
		float b[4];

		// left: voice count on a dark plate so the waveform does not cover it
		const float lw = nvgTextBounds(vg, 0, 0, left, NULL, b);
		nvgBeginPath(vg);
		nvgRect(vg, ix, iy, lw + pad * 2, th);
		nvgFillColor(vg, nvgRGBA(0, 0, 0, 150));
		nvgFill(vg);
		if (baseController->polyHover) {  // editable: outline the plate while hovered
			nvgBeginPath(vg);
			nvgRect(vg, ix + 0.5f, iy + 0.5f, lw + pad * 2 - 1.0f, th - 1.0f);
			nvgStrokeColor(vg, nvgRGBA(4, 186, 232, 220));
			nvgStrokeWidth(vg, 1.0f);
			nvgStroke(vg);
		}
		nvgFillColor(vg, total || baseController->polyHover ? nvgRGBA(255, 204, 153, 230) : nvgRGBA(255, 204, 153, 110));
		nvgText(vg, ix + pad, iy + 2.0f, left, NULL);

		// right: peak in dBFS (amber near 0 dB), and a red CLIP tag while latched
		const float pw = nvgTextBounds(vg, 0, 0, pk.c_str(), NULL, b);
		const float cw = right ? nvgTextBounds(vg, 0, 0, right, NULL, b) + pad * 2 + 2.0f : 0.0f;
		const float rx = ix + iw - pw - pad * 2 - cw;
		nvgBeginPath(vg);
		nvgRect(vg, rx, iy, pw + pad * 2 + cw, th);
		nvgFillColor(vg, nvgRGBA(0, 0, 0, 150));
		nvgFill(vg);
		const bool hot = peakHold >= 0.891f;  // -1 dBFS
		nvgFillColor(vg, peakHold < 1.0e-5f ? nvgRGBA(255, 204, 153, 110)
		                 : (hot ? nvgRGBA(255, 170, 60, 255) : nvgRGBA(255, 204, 153, 230)));
		nvgText(vg, rx + pad, iy + 2.0f, pk.c_str(), NULL);
		if (right) {
			const float cx = rx + pw + pad * 2 + 2.0f;
			nvgBeginPath(vg);
			nvgRect(vg, cx, iy, cw - 2.0f, th);
			nvgFillColor(vg, nvgRGBA(220, 20, 40, 230));
			nvgFill(vg);
			nvgFillColor(vg, nvgRGBA(255, 255, 255, 255));
			nvgText(vg, cx + pad, iy + 2.0f, right, NULL);
		}
		nvgRestore(vg);
	}

	void NVGView::drawScopeVoices(float ix, float iy, float iw, float ih) {
		// Sounding voices as bars behind the waveform. The x range follows the lowest..highest sounding
		// pitch (at least one octave, at most all 128; paramDisplay::voiceRange) and glides there, so
		// the bars are wide for a single note or a close chord and narrow for a wide spread.
		if (!baseController)
			return;
		const unsigned char* st = baseController->voiceStates;
		int tLo = 0, tHi = 0;
		paramDisplay::voiceRange(st, int(voiceViewLo + 0.5f), int(voiceViewHi + 0.5f), tLo, tHi);
		// Glide by time, not frames: widen fast (a new outer note shows within ~60 ms), narrow slowly.
		const auto now = std::chrono::steady_clock::now();
		float dt = voiceViewTimeValid ? std::chrono::duration<float>(now - voiceViewTime).count() : 1.0f;
		voiceViewTime = now;
		voiceViewTimeValid = true;
		if (dt > 1.0f) dt = 1.0f;
		const float kWiden = 1.0f - expf(-dt / 0.06f), kNarrow = 1.0f - expf(-dt / 0.25f);
		voiceViewLo += (float(tLo) - voiceViewLo) * (tLo < voiceViewLo ? kWiden : kNarrow);
		voiceViewHi += (float(tHi) - voiceViewHi) * (tHi > voiceViewHi ? kWiden : kNarrow);
		if (std::fabs(voiceViewLo - tLo) < 0.01f) voiceViewLo = float(tLo);
		if (std::fabs(voiceViewHi - tHi) < 0.01f) voiceViewHi = float(tHi);
		const float lo = voiceViewLo, slots = voiceViewHi - voiceViewLo + 1.0f;
		const float slotW = iw / slots;

		nvgSave(vg);
		nvgScissor(vg, ix, iy, iw, ih);

		// key backdrop: black-key slots slightly darker (only when wide enough to read)
		static const bool kBlack[12] = {false, true, false, true, false, false, true, false, true, false, true, false};
		const int p0 = (std::max)(0, int(floorf(lo)) - 1), p1 = (std::min)(127, int(ceilf(voiceViewHi)) + 1);
		if (slotW >= 3.0f) {
			nvgBeginPath(vg);
			for (int p = p0; p <= p1; p++)
				if (kBlack[p % 12])
					nvgRect(vg, ix + (p - lo) * slotW, iy, slotW, ih);
			nvgFillColor(vg, nvgRGBA(0, 0, 0, 90));
			nvgFill(vg);
		}
		// octave lines at every C, labelled when an octave is wide enough (MIDI 60 = C4)
		nvgFontSize(vg, 8.0f);
		nvgFontFace(vg, "mono");
		nvgTextAlign(vg, NVG_ALIGN_LEFT | NVG_ALIGN_BOTTOM);
		for (int p = p0; p <= p1; p++) {
			if (p % 12 != 0)
				continue;
			const float cx = floorf(ix + (p - lo) * slotW) + 0.5f;
			nvgBeginPath(vg);
			nvgMoveTo(vg, cx, iy);
			nvgLineTo(vg, cx, iy + ih);
			nvgStrokeColor(vg, nvgRGBA(4, 186, 232, 45));
			nvgStrokeWidth(vg, 1.0f);
			nvgStroke(vg);
			if (slotW * 12.0f >= 30.0f) {
				char name[8];
				snprintf(name, sizeof(name), "C%d", p / 12 - 1);
				nvgFillColor(vg, nvgRGBA(4, 186, 232, 110));
				nvgText(vg, cx + 2.0f, iy + ih - 1.0f, name, NULL);
			}
		}

		// bars: magenta while the key is held, cyan while releasing; height/brightness from the level
		for (int p = 0; p < 128; p++) {
			if (st[p] == 0)
				continue;
			const bool held = (st[p] & 0x80) != 0;
			const float level = float(st[p] & 0x7F) / 127.0f;
			const float a = 0.35f + 0.65f * sqrtf(level);
			const float bh = ih * (0.15f + 0.85f * sqrtf(level));
			const float bw = (std::max)(1.5f, slotW * 0.72f);
			const float bx = ix + (p - lo + 0.5f) * slotW - bw * 0.5f;
			const NVGcolor top = held ? nvgRGBA(255, 70, 205, (unsigned char)(150 * a)) : nvgRGBA(4, 186, 232, (unsigned char)(140 * a));
			const NVGcolor bottom = held ? nvgRGBA(255, 70, 205, (unsigned char)(25 * a)) : nvgRGBA(4, 186, 232, (unsigned char)(20 * a));
			nvgBeginPath(vg);
			nvgRect(vg, bx, iy + ih - bh, bw, bh);
			nvgFillPaint(vg, nvgLinearGradient(vg, 0, iy + ih - bh, 0, iy + ih, top, bottom));
			nvgFill(vg);
			// bright cap at the level
			nvgBeginPath(vg);
			nvgRect(vg, bx, iy + ih - bh, bw, (std::min)(2.0f, bh));
			nvgFillColor(vg, held ? nvgRGBA(255, 150, 235, (unsigned char)(230 * a)) : nvgRGBA(130, 230, 255, (unsigned char)(220 * a)));
			nvgFill(vg);
		}
		nvgRestore(vg);
	}

	void NVGView::drawRightColumn() {
		using namespace ::editorLayout;
		using namespace ::editorLayout::column;

		// 2026-11-16: no frame, separators or title for now; the content floats on the grid while the
		// final placement (and the logo) is worked out. kX0/kX1 still set the content edges.
		const float lx = kBoxL;  // label / box left edge (top of the frame's chamfer)
		const float rx = kBoxR;  // box right edge (the frame's right edge)

		// a bracket right of a box (2026-11-17)
		auto bracket = [&](float y0, float y1, NVGcolor c) {
			nvgBeginPath(vg);
			nvgMoveTo(vg, kBracketX - 4.0f, y0);
			nvgLineTo(vg, kBracketX, y0 + 4.0f);
			nvgLineTo(vg, kBracketX, y1 - 4.0f);
			nvgLineTo(vg, kBracketX - 4.0f, y1);
			nvgStrokeColor(vg, c);
			nvgStrokeWidth(vg, 1.5f);
			nvgStroke(vg);
		};

		// 4. Preset bar: < name > SAVE RND (drawPresetBar; PresetBarView handles the mouse)
		drawColumnSectionLabel(lx, kPreset.y0 + 2, "PRESET");
		drawInset(lx, kPreset.y0 + 17, rx - lx, kPreset.h() - 20, kColDimFrame);
		bracket(kPreset.y0 + 17, kPreset.y1 - 3, kColFrame);
		drawPresetBar();

		// 5. Readout: parameter name and value slots (text drawn by drawCtrlValueOutput)
		drawColumnSectionLabel(lx, kReadout.y0 + 2, "CONTROL");
		drawInset(lx, kReadout.y0 + 17, rx - lx, 20, kColMagenta);
		drawInset(lx, kReadout.y0 + 41, rx - lx, 20, kColMagenta);
		bracket(kReadout.y0 + 17, kReadout.y0 + 61, kColDivider);

		// 6. Scope: the latest output frame from the processor, over the sounding voices (drawScope)
		drawColumnSectionLabel(lx, kScope.y0 + 2, "SCOPE");
		drawInset(lx, kScope.y0 + 17, rx - lx, kScope.h() - 21, kColDimFrame);
		bracket(kScope.y0 + 17, kScope.y1 - 4, kColFrame);
		drawScope(lx, kScope.y0 + 17, rx - lx, kScope.h() - 21);

		// 7a. Frame around MASTER / PLAY / DELAY and CHORUS, with the section dividers
		drawColumnFrame();

		// 7. Master: volume and pan knobs (a divider between volume and the pan group)
		drawColumnSectionLabel(lx, kMaster.y0 + 2, "MASTER");
		drawKnobWell(kVolKnob, 11);
		{
			const float dx = floorf((kVolKnob.x + kVolKnob.w + kPanKnob.x) * 0.5f) + 0.5f;
			nvgBeginPath(vg);
			nvgMoveTo(vg, dx, kMaster.y0 + 18);
			nvgLineTo(vg, dx, kMaster.y1 - 4);
			nvgStrokeColor(vg, nvgRGBA(4, 186, 232, 70));
			nvgStrokeWidth(vg, 1.0f);
			nvgStroke(vg);
		}
		drawKnobWell(kPanKnob, 11);
		drawKnobWell(kPanAmtKnob, 11);
		drawKnobWell(kPanSrcKnob, 7);
		nvgFontSize(vg, 9.0f);
		nvgFontFace(vg, "mono");
		nvgTextAlign(vg, NVG_ALIGN_CENTER | NVG_ALIGN_TOP);
		nvgFillColor(vg, kColLabel);
		const float ly = kMaster.y1 - 10;
		nvgText(vg, kVolKnob.x + kVolKnob.w * 0.5f, ly, "VOLUME", NULL);
		nvgText(vg, kPanKnob.x + kPanKnob.w * 0.5f, ly, "PAN L/R", NULL);
		nvgText(vg, kPanAmtKnob.x + kPanAmtKnob.w * 0.5f, ly, "ENV AMT", NULL);
		nvgText(vg, kPanSrcKnob.x + kPanSrcKnob.w * 0.5f, ly, "ENV SRC", NULL);

		// 8. PLAY and FX rows (drawPlayPanel). The logo is gone; #moreInfo (the about window) now sits
		//    on the title.
		drawPlayPanel();
	}

