	void NVGView::drawMoreInfoBtn(RData& reIn) {
		// 2026-11-18: the button covers the logo, whose hover/press effect drawLogo draws (over the
		// logo); the old cyan outline would sit under the logo image, so nothing is drawn here.
		return;
		RSBView* rsbView = &RViewsMap.at("MORE_INFO_BTN");
		//build info button
		nvgBeginPath(vg);
		nvgMoveTo(vg, moreInfoBtn->pathOutline[0].x, moreInfoBtn->pathOutline[0].y);
		nvgLineTo(vg, moreInfoBtn->pathOutline[1].x, moreInfoBtn->pathOutline[1].y);
		nvgLineTo(vg, moreInfoBtn->pathOutline[2].x, moreInfoBtn->pathOutline[2].y);
		nvgLineTo(vg, moreInfoBtn->pathOutline[3].x, moreInfoBtn->pathOutline[3].y);
		nvgLineTo(vg, moreInfoBtn->pathOutline[4].x, moreInfoBtn->pathOutline[4].y);
		nvgLineTo(vg, moreInfoBtn->pathOutline[5].x, moreInfoBtn->pathOutline[5].y);
		nvgLineTo(vg, moreInfoBtn->pathOutline[6].x, moreInfoBtn->pathOutline[6].y);
		nvgLineTo(vg, moreInfoBtn->pathOutline[7].x, moreInfoBtn->pathOutline[7].y);
		nvgLineTo(vg, moreInfoBtn->pathOutline[0].x, moreInfoBtn->pathOutline[0].y);

		nvgClosePath(vg);
		// The button now sits on the logo: a cyan hover glow instead of the old white fill.
		nvgFillColor(vg, nvgRGBA(4, 186, 232, (int)(45.0 * rsbView->blinkIntensity)));
		nvgFill(vg);
		nvgStrokeColor(vg, nvgRGBA(4, 186, 232, (int)(255.0 * rsbView->blinkIntensity)));
		nvgStrokeWidth(vg, 1.5f);
		nvgStroke(vg);

		

	}

	
	std::string NVGView::getCopyright() {
		// Get the current year
		time_t now = time(0);
		tm* ltm = localtime(&now);
		int year = 1900 + ltm->tm_year;

		// Create the copyright string
		const std::string copyrightSymbol = "\u00A9";
		std::string yearStr = std::to_string(year);

		// Construct the result string
		std::string result = copyrightSymbol + yearStr + " Rogue Syntax Sound Design, LLC.";

		return result;
	}
	

	// Logo with its hover effect (2026-11-18). The logo is the about button (#moreInfo covers it).
	// Hovered (eased in/out): a magenta ghost halo breathing behind it, a faint drifting ghost double
	// over it, a light sheen sweeping across, a lit border with two sparks running around it (fading
	// tails). Clicked (MORE_INFO_BTN blink): a white flash and a 1 px dip.
	void NVGView::drawLogo() {
		using namespace ::editorLayout;
		if (images[DM_LOGO] <= 0)
			return;
		static const auto t0 = std::chrono::steady_clock::now();
		const double t = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
		const float dt = logoLastT < 0.0 ? 0.0f : static_cast<float>((std::min)(0.1, t - logoLastT));
		logoLastT = t;
		const bool hovered = (moreInfoPhase == 1 || logoHoverForce) && !moreInfoWindowOpen;
		logoHover += ((hovered ? 1.0f : 0.0f) - logoHover) * (std::min)(1.0f, dt * 9.0f);
		if (logoHover < 0.002f) logoHover = 0.0f;
		const float h = logoHover;
		float flash = 0.0f;
		{
			auto it = RViewsMap.find("MORE_INFO_BTN");
			if (it != RViewsMap.end())
				flash = static_cast<float>(it->second.blinkIntensity);
		}
		const float x = kLogoImg.x, y = kLogoImg.y + (flash > 0.05f ? 1.0f : 0.0f);
		const float w = kLogoImg.w, ht = kLogoImg.h;
		const float cx = x + w * 0.5f, cy = y + ht * 0.5f;
		const float kTwoPi = 6.2831853f;

		// image drawn at a scale around the centre, tinted (the shader multiplies by the paint colour)
		auto logoCopy = [&](float s, float dx, float dy, NVGcolor tint) {
			const float sw = w * s, sh = ht * s;
			const float sx = cx - sw * 0.5f + dx, sy = cy - sh * 0.5f + dy;
			NVGpaint p = nvgImagePattern(vg, sx, sy, sw, sh, 0.0f, images[DM_LOGO], 1.0f);
			p.innerColor = tint;
			nvgBeginPath(vg);
			nvgRect(vg, sx, sy, sw, sh);
			nvgFillPaint(vg, p);
			nvgFill(vg);
		};

		// 1. ghost halo behind: a soft glow box and enlarged magenta copies, breathing
		const float breathe = 0.5f + 0.5f * sinf(static_cast<float>(t) * kTwoPi / 2.6f);
		if (h > 0.0f) {
			nvgSave(vg);
			nvgGlobalCompositeOperation(vg, NVG_LIGHTER);
			nvgBeginPath(vg);
			nvgRect(vg, x - 16, y - 16, w + 32, ht + 32);
			nvgFillPaint(vg, nvgBoxGradient(vg, x, y, w, ht, 4.0f, 14.0f + 6.0f * breathe,
			                                nvgRGBA(255, 60, 200, (unsigned char)(70 * h)), nvgRGBA(255, 60, 200, 0)));
			nvgFill(vg);
			for (int i = 1; i <= 3; i++) {
				const float s = 1.0f + i * (0.012f + 0.008f * breathe);
				logoCopy(s, 0, 0, nvgRGBAf(1.0f, 0.35f, 0.85f, h * (0.16f - 0.04f * i)));
			}
			nvgRestore(vg);
		}

		// 2. the logo
		drawImageAt(DM_LOGO, x, y, w, ht);

		nvgSave(vg);
		nvgScissor(vg, x, y, w, ht);
		nvgGlobalCompositeOperation(vg, NVG_LIGHTER);
		if (h > 0.0f) {
			// 3. ghost double: a faint copy drifting a pixel or two around the logo
			const float gx = 1.6f * sinf(static_cast<float>(t) * 1.7f), gy = 1.0f * sinf(static_cast<float>(t) * 2.3f + 1.0f);
			logoCopy(1.0f, gx, gy, nvgRGBAf(0.7f, 0.9f, 1.0f, h * (0.10f + 0.06f * breathe)));

			// 4. sheen: a slanted light band sweeping left to right every 2.4 s (then a pause)
			const float period = 2.4f, sweep = 0.9f;
			const float ph = fmodf(static_cast<float>(t), period) / sweep;
			if (ph < 1.0f) {
				const float bw = 26.0f;
				const float bx = x - 40.0f + (w + 80.0f) * ph;
				nvgSave(vg);
				nvgTranslate(vg, bx, y);
				nvgSkewX(vg, -0.45f);
				const NVGcolor c0 = nvgRGBA(255, 230, 250, 0), c1 = nvgRGBA(255, 230, 250, (unsigned char)(90 * h));
				nvgBeginPath(vg);
				nvgRect(vg, -bw, 0, bw, ht);
				nvgFillPaint(vg, nvgLinearGradient(vg, -bw, 0, 0, 0, c0, c1));
				nvgFill(vg);
				nvgBeginPath(vg);
				nvgRect(vg, 0, 0, bw, ht);
				nvgFillPaint(vg, nvgLinearGradient(vg, 0, 0, bw, 0, c1, c0));
				nvgFill(vg);
				nvgRestore(vg);
			}
		}
		// 7. click flash
		if (flash > 0.0f) {
			nvgBeginPath(vg);
			nvgRect(vg, x, y, w, ht);
			nvgFillColor(vg, nvgRGBA(255, 255, 255, (unsigned char)(80 * flash)));
			nvgFill(vg);
		}
		nvgRestore(vg);

		if (h <= 0.0f && flash <= 0.0f)
			return;

		// 5. lit border (inset 1 px) and 6. two sparks running around it, clockwise
		const float bx0 = x + 1.0f, by0 = y + 1.0f, bx1 = x + w - 1.0f, by1 = y + ht - 1.0f;
		const float bw = bx1 - bx0, bh = by1 - by0, per = 2.0f * (bw + bh);
		auto at = [&](float d, float& px, float& py) {
			d = fmodf(d, per);
			if (d < 0) d += per;
			if (d < bw) { px = bx0 + d; py = by0; return; }
			d -= bw;
			if (d < bh) { px = bx1; py = by0 + d; return; }
			d -= bh;
			if (d < bw) { px = bx1 - d; py = by1; return; }
			d -= bw;
			px = bx0; py = by1 - d;
		};
		nvgSave(vg);
		nvgGlobalCompositeOperation(vg, NVG_LIGHTER);
		nvgLineJoin(vg, NVG_MITER);
		const float lit = (std::max)(h, flash);
		nvgBeginPath(vg);
		nvgRect(vg, bx0, by0, bw, bh);
		nvgStrokeColor(vg, nvgRGBA(4, 186, 232, (unsigned char)(60 * lit)));
		nvgStrokeWidth(vg, 5.0f);
		nvgStroke(vg);
		nvgStrokeColor(vg, nvgRGBA(110, 225, 255, (unsigned char)(150 * lit + 105 * flash)));
		nvgStrokeWidth(vg, 1.5f);
		nvgStroke(vg);

		if (h > 0.0f) {
			const float head0 = fmodf(static_cast<float>(t) / 1.8f, 1.0f) * per;  // once around in 1.8 s
			const float tail = 90.0f, step = 3.0f;
			nvgLineCap(vg, NVG_ROUND);
			for (int s = 0; s < 2; s++) {
				const float head = head0 + s * per * 0.5f;
				float px, py, qx, qy;
				for (float d = tail; d > 0.0f; d -= step) {
					at(head - d, px, py);
					at(head - d + step, qx, qy);
					const float k = 1.0f - d / tail;  // 0 at the end of the tail, 1 at the head
					nvgBeginPath(vg);
					nvgMoveTo(vg, px, py);
					nvgLineTo(vg, qx, qy);
					nvgStrokeColor(vg, nvgRGBA(4, 186, 232, (unsigned char)(110 * h * k)));
					nvgStrokeWidth(vg, 6.0f);
					nvgStroke(vg);
					nvgStrokeColor(vg, nvgRGBA(220, 250, 255, (unsigned char)(230 * h * k * k)));
					nvgStrokeWidth(vg, 2.0f);
					nvgStroke(vg);
				}
				// bright head
				at(head, px, py);
				nvgBeginPath(vg);
				nvgCircle(vg, px, py, 7.0f);
				nvgFillPaint(vg, nvgRadialGradient(vg, px, py, 0.5f, 7.0f, nvgRGBA(255, 255, 255, (unsigned char)(230 * h)), nvgRGBA(4, 186, 232, 0)));
				nvgFill(vg);
			}
		}
		nvgRestore(vg);
	}

	// CREDITS page of the about screen (2026-11-18): the third-party notices (creditsText.h, generated
	// from licenses/THIRD-PARTY-NOTICES.txt by tools/gen_notices.ps1), scrolled with the mouse wheel
	// (AboutLinksView), with a scroll bar on the right.
	void NVGView::drawAboutCredits() {
		using namespace ::editorLayout;
		using namespace ::editorLayout::about;
		const float ax = static_cast<float>(kCreditsArea.x), ay = static_cast<float>(kCreditsArea.y);
		const float aw = static_cast<float>(kCreditsArea.w), ah = static_cast<float>(kCreditsArea.h);
		const float scroll = baseController ? baseController->aboutScroll : 0.0f;
		nvgSave(vg);
		nvgScissor(vg, ax - 2, ay, aw + 4, ah);
		nvgFontFace(vg, "mono");
		nvgTextAlign(vg, NVG_ALIGN_LEFT | NVG_ALIGN_TOP);
		float yy = ay - scroll;
		for (int i = 0; i < credits::kCount; i++) {
			const char* p = credits::kText[i];
			const bool heading = p[0] == '#' && p[1] == '#' && p[2] == ' ';
			if (heading) {
				p += 3;
				if (i > 0)
					yy += 10.0f;
				nvgFontSize(vg, 11.0f);
				nvgTextLineHeight(vg, 1.2f);
				nvgFillColor(vg, nvgRGBA(150, 235, 255, 255));
			}
			else {
				nvgFontSize(vg, 9.0f);
				nvgTextLineHeight(vg, 1.3f);
				nvgFillColor(vg, nvgRGBA(225, 190, 235, 235));
			}
			float b[4];
			nvgTextBoxBounds(vg, ax, yy, aw - 14.0f, p, NULL, b);
			if (b[3] >= ay && b[1] <= ay + ah)  // only what shows
				nvgTextBox(vg, ax, yy, aw - 14.0f, p, NULL);
			if (heading) {
				nvgBeginPath(vg);
				nvgMoveTo(vg, ax, floorf(b[3] + 3.0f) + 0.5f);
				nvgLineTo(vg, ax + aw - 14.0f, floorf(b[3] + 3.0f) + 0.5f);
				nvgStrokeColor(vg, nvgRGBA(176, 60, 190, 110));
				nvgStrokeWidth(vg, 1.0f);
				nvgStroke(vg);
			}
			yy = b[3] + (heading ? 8.0f : 6.0f);
		}
		nvgTextLineHeight(vg, 1.0f);
		nvgRestore(vg);

		// content height -> scroll limit; scroll bar
		const float content = yy + scroll - ay;
		const float maxScroll = (std::max)(0.0f, content - ah);
		if (baseController) {
			baseController->aboutScrollMax = maxScroll;
			if (baseController->aboutScroll > maxScroll)
				baseController->aboutScroll = maxScroll;
		}
		if (maxScroll > 0.0f) {
			const float bx = ax + aw - 4.0f;
			nvgBeginPath(vg);
			nvgRect(vg, bx, ay, 3.0f, ah);
			nvgFillColor(vg, nvgRGBA(176, 60, 190, 50));
			nvgFill(vg);
			const float th = (std::max)(20.0f, ah * ah / content);
			const float ty = ay + (ah - th) * (scroll / maxScroll);
			nvgBeginPath(vg);
			nvgRect(vg, bx, ty, 3.0f, th);
			nvgFillColor(vg, nvgRGBA(4, 186, 232, 220));
			nvgFill(vg);
		}
		// fades at the edges of the text area
		nvgBeginPath(vg);
		nvgRect(vg, ax - 2, ay, aw - 10, 10);
		nvgFillPaint(vg, nvgLinearGradient(vg, 0, ay, 0, ay + 10, nvgRGBA(6, 8, 15, scroll > 0.5f ? 230 : 0), nvgRGBA(6, 8, 15, 0)));
		nvgFill(vg);
		nvgBeginPath(vg);
		nvgRect(vg, ax - 2, ay + ah - 14, aw - 10, 14);
		nvgFillPaint(vg, nvgLinearGradient(vg, 0, ay + ah - 14, 0, ay + ah, nvgRGBA(6, 8, 15, 0),
		                                   nvgRGBA(6, 8, 15, scroll < maxScroll - 0.5f ? 230 : 0)));
		nvgFill(vg);
	}

	void NVGView::drawMoreInfoWindow() {
		//info window
		// 2026-11-18: drawn in code (was dm_about_window.png drawn whole: its transparent surround let
		// the panel show through and its box was placed for the old 1148 px window). The panel stays
		// visible, dimmed, behind a centred box; the two logos are cut from dm_about_window.png.
		if (!moreInfoWindowOpen)
			return;
		using namespace ::editorLayout;
		using namespace ::editorLayout::about;
		static const auto t0 = std::chrono::steady_clock::now();
		const float t = std::chrono::duration<float>(std::chrono::steady_clock::now() - t0).count();
		const NVGcolor kPink = nvgRGBA(255, 153, 255, 255);
		const NVGcolor kMag = nvgRGBA(176, 60, 190, 255);
		const NVGcolor kMagDim = nvgRGBA(176, 60, 190, 110);
		const float x = static_cast<float>(kBox.x), y = static_cast<float>(kBox.y);
		const float w = static_cast<float>(kBox.w), h = static_cast<float>(kBox.h);
		const float cx = x + w * 0.5f;

		// backdrop: the whole window dimmed, darker towards the edges
		nvgBeginPath(vg);
		nvgRect(vg, 0, 0, static_cast<float>(kEditorWidth), static_cast<float>(kEditorHeight));
		nvgFillColor(vg, nvgRGBA(2, 5, 10, 205));
		nvgFill(vg);
		nvgBeginPath(vg);
		nvgRect(vg, 0, 0, static_cast<float>(kEditorWidth), static_cast<float>(kEditorHeight));
		nvgFillPaint(vg, nvgRadialGradient(vg, cx, y + h * 0.5f, h * 0.45f, static_cast<float>(kEditorWidth) * 0.6f,
		                                   nvgRGBA(0, 0, 0, 0), nvgRGBA(0, 0, 0, 120)));
		nvgFill(vg);

		// box: soft magenta glow, opaque body, chamfered magenta border
		const float c1 = 8.0f, c2 = 14.0f;
		auto boxPath = [&]() {
			nvgBeginPath(vg);
			nvgMoveTo(vg, x + c1, y);
			nvgLineTo(vg, x + w, y);
			nvgLineTo(vg, x + w, y + h - c2);
			nvgLineTo(vg, x + w - c2, y + h);
			nvgLineTo(vg, x, y + h);
			nvgLineTo(vg, x, y + c1);
			nvgClosePath(vg);
		};
		nvgBeginPath(vg);
		nvgRect(vg, x - 30, y - 30, w + 60, h + 60);
		nvgFillPaint(vg, nvgBoxGradient(vg, x, y, w, h, 6.0f, 26.0f, nvgRGBA(176, 60, 190, 70), nvgRGBA(176, 60, 190, 0)));
		nvgFill(vg);
		boxPath();
		nvgFillPaint(vg, nvgLinearGradient(vg, 0, y, 0, y + h, nvgRGBA(12, 16, 28, 255), nvgRGBA(5, 6, 12, 255)));
		nvgFill(vg);
		nvgSave(vg);
		nvgScissor(vg, x, y, w, h);
		fillGrid(x, y + kTitleH, w, h - kTitleH);  // the panel's grid, faint inside the box
		nvgBeginPath(vg);
		nvgRect(vg, x, y + kTitleH, w, h - kTitleH);
		nvgFillColor(vg, nvgRGBA(5, 7, 14, 190));
		nvgFill(vg);
		nvgRestore(vg);
		boxPath();
		nvgLineJoin(vg, NVG_MITER);
		nvgStrokeColor(vg, kMag);
		nvgStrokeWidth(vg, 2.0f);
		nvgStroke(vg);

		// title bar: ABOUT, a divider, the close box (#shutWin)
		nvgBeginPath(vg);
		nvgMoveTo(vg, x, y + kTitleH + 0.5f);
		nvgLineTo(vg, x + w, y + kTitleH + 0.5f);
		nvgStrokeColor(vg, kMagDim);
		nvgStrokeWidth(vg, 1.0f);
		nvgStroke(vg);
		// ABOUT / CREDITS tabs (AboutLinksView switches them): the active one lit with an underline
		const bool credits = baseController && baseController->aboutCredits;
		{
			const int hov = baseController ? baseController->aboutHover : -1;
			const ImageRect tabs[2] = {kTabAbout, kTabCredits};
			const char* names[2] = {"ABOUT", "CREDITS"};
			nvgFontSize(vg, 11.0f);
			nvgFontFace(vg, "mono");
			nvgTextAlign(vg, NVG_ALIGN_CENTER | NVG_ALIGN_MIDDLE);
			for (int i = 0; i < 2; i++) {
				const ImageRect& r = tabs[i];
				const bool active = (i == 1) == credits;
				const bool hot = hov == aboutLinks::kTabAbout + i;
				if (hot && !active) {
					nvgBeginPath(vg);
					nvgRect(vg, static_cast<float>(r.x), static_cast<float>(r.y) + 1, static_cast<float>(r.w), static_cast<float>(r.h) - 1);
					nvgFillColor(vg, nvgRGBA(4, 186, 232, 35));
					nvgFill(vg);
				}
				nvgFillColor(vg, active ? nvgRGBA(150, 235, 255, 255) : (hot ? nvgRGBA(120, 210, 240, 255) : nvgRGBA(4, 186, 232, 150)));
				nvgText(vg, r.x + r.w * 0.5f, r.y + r.h * 0.5f + 1.0f, names[i], NULL);
				if (active) {
					nvgBeginPath(vg);
					nvgMoveTo(vg, static_cast<float>(r.x) + 6, r.y + r.h - 1.5f);
					nvgLineTo(vg, static_cast<float>(r.x + r.w) - 6, r.y + r.h - 1.5f);
					nvgStrokeColor(vg, nvgRGBA(4, 186, 232, 255));
					nvgStrokeWidth(vg, 2.0f);
					nvgStroke(vg);
				}
			}
		}
		{
			const float bx = static_cast<float>(kClose.x), by = static_cast<float>(kClose.y);
			const float bw = static_cast<float>(kClose.w), bh = static_cast<float>(kClose.h);
			nvgBeginPath(vg);
			nvgRect(vg, bx, by, bw, bh);
			nvgFillColor(vg, shutHover ? nvgRGBA(176, 60, 190, 150) : nvgRGBA(40, 20, 70, 200));
			nvgFill(vg);
			nvgBeginPath(vg);
			nvgMoveTo(vg, bx + 0.5f, by);
			nvgLineTo(vg, bx + 0.5f, by + bh);
			nvgStrokeColor(vg, kMag);
			nvgStrokeWidth(vg, 1.0f);
			nvgStroke(vg);
			const float mx = bx + bw * 0.5f, my = by + bh * 0.5f, s = 5.0f;
			nvgBeginPath(vg);
			nvgMoveTo(vg, mx - s, my - s);
			nvgLineTo(vg, mx + s, my + s);
			nvgMoveTo(vg, mx + s, my - s);
			nvgLineTo(vg, mx - s, my + s);
			nvgStrokeColor(vg, shutHover ? nvgRGBA(255, 255, 255, 255) : nvgRGBA(130, 200, 255, 230));
			nvgStrokeWidth(vg, 1.5f);
			nvgStroke(vg);
		}

		if (credits)
			drawAboutCredits();
		else {
		// logo, with a breathing halo
		float ly = y + kTitleH + 20.0f;
		if (images[DM_LOGO] > 0) {
			const float lw = static_cast<float>(kLogoImg.w), lh = static_cast<float>(kLogoImg.h);
			const float lx = floorf(cx - lw * 0.5f);
			const float br = 0.5f + 0.5f * sinf(t * 6.2831853f / 2.6f);
			nvgBeginPath(vg);
			nvgRect(vg, lx - 24, ly - 24, lw + 48, lh + 48);
			nvgFillPaint(vg, nvgBoxGradient(vg, lx, ly, lw, lh, 4.0f, 14.0f + 8.0f * br,
			                                nvgRGBA(255, 60, 200, (unsigned char)(50 + 40 * br)), nvgRGBA(255, 60, 200, 0)));
			nvgFill(vg);
			drawImageAt(DM_LOGO, lx, ly, lw, lh);
			ly += lh;
		}

		// version
		nvgFontFace(vg, "mono");
		nvgFontSize(vg, 16.0f);
		nvgTextAlign(vg, NVG_ALIGN_CENTER | NVG_ALIGN_TOP);
		nvgFillColor(vg, kPink);
		std::string ver = version;
		for (char& ch : ver) ch = static_cast<char>(toupper(static_cast<unsigned char>(ch)));
		nvgText(vg, cx, ly + 14.0f, ver.c_str(), NULL);

		// Rogue Syntax and VST logos, cut from the old about art
		const float rowY = ly + 40.0f;
		auto cut = [&](const ImageRect& src, float dx, float dy) {
			if (images[DM_ABOUT_WINDOW] <= 0)
				return;
			NVGpaint p = nvgImagePattern(vg, dx - src.x, dy - src.y, static_cast<float>(kAboutImg.w), static_cast<float>(kAboutImg.h),
			                             0.0f, images[DM_ABOUT_WINDOW], 1.0f);
			nvgBeginPath(vg);
			nvgRect(vg, dx, dy, static_cast<float>(src.w), static_cast<float>(src.h));
			nvgFillPaint(vg, p);
			nvgFill(vg);
		};
		const float pad = kPad;
		cut(kRogueSrc, x + pad, rowY);
		cut(kVstSrc, x + w - pad - kVstSrc.w, rowY - 1.5f);

		// description, two paragraphs with a divider between them
		const float tx = x + pad, tw = w - 2.0f * pad;
		float ty = rowY + 62.0f + 16.0f;
		nvgFontSize(vg, 11.0f);
		nvgTextAlign(vg, NVG_ALIGN_LEFT | NVG_ALIGN_TOP);
		nvgTextLineHeight(vg, 1.35f);
		nvgFillColor(vg, kPink);
		static const char* const kPara[2] = {
			"A numerically-controlled oscillator poly synth designed for long, rich plucked sounds, punctuating bass, and FM mayhem.",
			"Built in the same tactile vein as your favorite tabletop synths - knobs, switches, sliders and pads.",
		};
		for (int i = 0; i < 2; i++) {
			float b[4];
			nvgTextBoxBounds(vg, tx, ty, tw, kPara[i], NULL, b);
			nvgTextBox(vg, tx, ty, tw, kPara[i], NULL);
			ty = b[3] + 8.0f;
			if (i == 0) {
				nvgBeginPath(vg);
				nvgMoveTo(vg, tx, floorf(ty) + 0.5f);
				nvgLineTo(vg, tx + tw, floorf(ty) + 0.5f);
				nvgStrokeColor(vg, kMag);
				nvgStrokeWidth(vg, 1.0f);
				nvgStroke(vg);
				ty += 9.0f;
			}
		}
		nvgTextLineHeight(vg, 1.0f);

		// links row (clickable through AboutLinksView) and info row, under a divider
		nvgBeginPath(vg);
		nvgMoveTo(vg, tx, kInfoLineY + 0.5f);
		nvgLineTo(vg, tx + tw, kInfoLineY + 0.5f);
		nvgStrokeColor(vg, kMagDim);
		nvgStrokeWidth(vg, 1.0f);
		nvgStroke(vg);
		{
			const int hov = baseController ? baseController->aboutHover : -1;
			const ImageRect zones[2] = {kWebZone, kMailZone};
			const char* texts[2] = {"WWW.ROGUE-SYNTAX.COM", "ADMIN@ROGUE-SYNTAX.COM"};
			nvgFontSize(vg, 11.0f);
			for (int i = 0; i < 2; i++) {
				const ImageRect& z = zones[i];
				const bool hot = hov == i;
				const float zy = z.y + z.h * 0.5f;
				if (hot) {
					nvgBeginPath(vg);
					nvgRect(vg, static_cast<float>(z.x) - 4, static_cast<float>(z.y), static_cast<float>(z.w) + 8, static_cast<float>(z.h));
					nvgFillColor(vg, nvgRGBA(4, 186, 232, 40));
					nvgFill(vg);
				}
				nvgTextAlign(vg, (i == 0 ? NVG_ALIGN_LEFT : NVG_ALIGN_RIGHT) | NVG_ALIGN_MIDDLE);
				const float txx = i == 0 ? static_cast<float>(z.x) : static_cast<float>(z.x + z.w);
				nvgFillColor(vg, hot ? nvgRGBA(220, 250, 255, 255) : nvgRGBA(4, 186, 232, 255));
				nvgText(vg, txx, zy + 1.0f, texts[i], NULL);
				// underline (the text's own width)
				const float tw2 = nvgTextBounds(vg, 0, 0, texts[i], NULL, nullptr);
				const float ux0 = i == 0 ? txx : txx - tw2;
				nvgBeginPath(vg);
				nvgMoveTo(vg, ux0, floorf(zy + 8.0f) + 0.5f);
				nvgLineTo(vg, ux0 + tw2, floorf(zy + 8.0f) + 0.5f);
				nvgStrokeColor(vg, hot ? nvgRGBA(220, 250, 255, 230) : nvgRGBA(4, 186, 232, 90));
				nvgStrokeWidth(vg, 1.0f);
				nvgStroke(vg);
			}
		}
		{
			// registration (left) and format / build (right)
			// build stamp: branch, commit and build time, written at every build (tools/buildstamp.ps1;
			// __DATE__ used to be here, but that is when this file was last compiled, not the build)
			const std::string fmt = std::string("VST3  |  64-BIT  |  BUILD ") + kBuildStamp;
			nvgFontSize(vg, 10.0f);
			// licensing v1: who it is licensed to; the email goes first, then the name is cut, if the
			// line would run into the build stamp
			const bool reg = baseController && baseController->licensed;
			std::string lic = "UNLICENSED";
			if (reg) {
				const license::License& li = baseController->licenseInfo;
				std::string tag = li.kind == "dev" ? "  |  DEV" : (li.kind == "nfr" ? "  |  NFR" : "");
				const float room = tw - nvgTextBounds(vg, 0, 0, fmt.c_str(), NULL, NULL) - 24.0f;
				std::string name = li.name;
				lic = "LICENSED TO " + name + (li.email.empty() ? "" : "  (" + li.email + ")") + tag;
				if (nvgTextBounds(vg, 0, 0, lic.c_str(), NULL, NULL) > room)
					lic = "LICENSED TO " + name + tag;
				while (nvgTextBounds(vg, 0, 0, lic.c_str(), NULL, NULL) > room && !name.empty()) {
					name.pop_back();
					while (!name.empty() && (static_cast<unsigned char>(name.back()) & 0xC0) == 0x80)
						name.pop_back();  // keep whole UTF-8 characters
					lic = "LICENSED TO " + name + "..." + tag;
				}
			}
			nvgTextAlign(vg, NVG_ALIGN_LEFT | NVG_ALIGN_MIDDLE);
			nvgFillColor(vg, reg ? nvgRGBA(120, 235, 170, 255) : nvgRGBA(255, 150, 80, 255));
			nvgText(vg, tx, kInfoY, lic.c_str(), NULL);
			nvgTextAlign(vg, NVG_ALIGN_RIGHT | NVG_ALIGN_MIDDLE);
			nvgFillColor(vg, nvgRGBA(150, 160, 185, 230));
			nvgText(vg, tx + tw, kInfoY, fmt.c_str(), NULL);
		}
		}  // about page

		// footer: divider with a 45 degree step, copyright left, trademark notice right
		const float fy = y + h - 30.0f;
		nvgBeginPath(vg);
		nvgMoveTo(vg, x, fy + 0.5f);
		nvgLineTo(vg, x + w, fy + 0.5f);
		nvgMoveTo(vg, x + 222.0f, y + h);
		nvgLineTo(vg, x + 252.0f, fy + 0.5f);
		nvgStrokeColor(vg, kMagDim);
		nvgStrokeWidth(vg, 1.0f);
		nvgStroke(vg);
		nvgFontSize(vg, 9.0f);
		nvgTextAlign(vg, NVG_ALIGN_LEFT | NVG_ALIGN_MIDDLE);
		nvgFillColor(vg, kColLabel);
		nvgText(vg, x + 14.0f, fy + 15.0f, copyw.c_str(), NULL);
		nvgTextAlign(vg, NVG_ALIGN_RIGHT | NVG_ALIGN_MIDDLE);
		nvgFillColor(vg, nvgRGBA(235, 235, 245, 230));
		nvgText(vg, x + w - 14.0f, fy + 15.0f, "VST is a registered trademark of Steinberg Media Technologies GmbH", NULL);
	}

	void NVGView::onMoreInfoBtnEnter() {
		this->moreInfoPhase = 1;
		// readout (CONTROL slots) while the logo / about button is hovered
		if (!moreInfoWindowOpen) {
			std::string v = version + "  CLICK FOR INFO";  // version: "Version x.y.z"
			for (char& ch : v) ch = static_cast<char>(toupper(static_cast<unsigned char>(ch)));
			targDisplayTxt.reset("ABOUT DONNA MEDINA", "#logo", 0.025f, 0.025f);
			targValueTxt.reset(v.c_str(), "#logo", 0.013f, 0.013f);
			targDisplayTxt.hold = true;
			targValueTxt.hold = true;
		}
	};

	void NVGView::onMoreInfoBtnExit() {
		this->moreInfoPhase = 0;
		targDisplayTxt.hold = false;
		targValueTxt.hold = false;
	};

	void NVGView::onMoreInfoBtnDown() {
		//SHOW BLINK
		Anima ar;
		ar.animName = BUTTON_BLINK_FASTEST;
		ar.controlIdx = MORE_INFO_BUTTON_VIEW_IDX;
		ar.animState = 0;

		RSBView* rsbView = &RViewsMap.at("MORE_INFO_BTN");
		for (auto it = animationReel.begin(); it != animationReel.end(); ++it) {
			if (it->animName == ar.animName && it->controlIdx == ar.controlIdx) {
				animationReel.erase(it);
				break;
			}
		}
		rsbView->blinkIntensity = 0.0;
		rsbView->blinker = 0.0;
		rsbView->blinkerDone = false;

		animationReel.push_back(ar);

		//TOGGLE MAIN WINDOW
		if (moreInfoWindowOpen == false) {
			moreInfoWindowOpen = true;
			for (int i = 0; i < 1000; i++) {
				if (controlMap[i] != nullptr ) {
					controlMap[i]->setMouseEnabled(false);
				}
			}
			if (controlMap[SHUT_WIN_BUTTON_VIEW_IDX] != nullptr) {
				controlMap[SHUT_WIN_BUTTON_VIEW_IDX]->setMouseEnabled(true);
			}
		}
		else {
			moreInfoWindowOpen = false;
			for (int i = 0; i < 1000; i++) {
				if (controlMap[i] != nullptr) {
					controlMap[i]->setMouseEnabled(true);
				}
			}
			if (controlMap[SHUT_WIN_BUTTON_VIEW_IDX] != nullptr) {
				controlMap[SHUT_WIN_BUTTON_VIEW_IDX]->setMouseEnabled(false);
			}
		}
		syncAboutViews();
	}


	// Views that only work while the about screen is open (2026-11-18): the links row.
	void NVGView::syncAboutViews() {
		if (!baseController)
			return;
		if (baseController->aboutLinksView)
			baseController->aboutLinksView->setMouseEnabled(moreInfoWindowOpen);
		if (!moreInfoWindowOpen) {
			baseController->aboutHover = -1;
			baseController->aboutCredits = false;  // opens on the about page
			baseController->aboutScroll = 0.0f;
		}
		shutHover = false;
	}

	void NVGView::onShutWinBtnDown() {
		//SHOW BLINK
		Anima ar;
		ar.animName = BUTTON_BLINK_FASTEST;
		ar.controlIdx = SHUT_WIN_BUTTON_VIEW_IDX;
		ar.animState = 0;

		RSBView* rsbView = &RViewsMap.at("SHUT_WIN_BTN");
		int reelSize = static_cast<int>(animationReel.size());
		for (int i = 0; i < reelSize; ) {
			if (animationReel[i].animName == ar.animName && animationReel[i].controlIdx == ar.controlIdx) {
				animationReel.erase(animationReel.begin() + i);
				reelSize--; // Adjust the size
			}
			else {
				i++; // Only increment if no erase
			}
		}
		rsbView->blinkIntensity = 0.0;
		rsbView->blinker = 0.0;
		rsbView->blinkerDone = false;

		animationReel.push_back(ar);

		//TOGGLE MAIN WINDOW
		if (moreInfoWindowOpen == false) {
			moreInfoWindowOpen = true;
			for (int i = 0; i < 1000; i++) {
				if (controlMap[i] != nullptr) {
					controlMap[i]->setMouseEnabled(false);
				}
			}
		}
		else {
			moreInfoWindowOpen = false;
			for (int i = 0; i < 1000; i++) {
				if (controlMap[i] != nullptr) {
					controlMap[i]->setMouseEnabled(true);
				}
			}
			if (controlMap[SHUT_WIN_BUTTON_VIEW_IDX] != nullptr) {
				controlMap[SHUT_WIN_BUTTON_VIEW_IDX]->setMouseEnabled(false);
			}
		}
		syncAboutViews();
	}

